  if("'!/''^(?:'"\\d+(?:\\.\\d+)?|\\.\\d+)"'$/.test(t.text))fail(t,'"'Oczekiwano wyrażenia liczbowego.');
  this.take();return {token:t,kind:'number',value:Number(t.text)};
 }
 body(depth=0):Node[]{
  const nodes:Node[]=[];
  while(this.peek()&&this.peek().text"'!=='"']'){
   const token=[REDACTED_SECRET]
   if("'!cmd)fail(token,`Nieznane polecenie „${token.text}”.`);
   const n:Node={token,cmd,args:[]};
   if(['"'fd','bk','rt','lt','width','repeat'].includes(cmd))n.args.push(this.expression(token));
   else if(cmd==='color'){
    const color=this.take();if("'!color)fail(token,'"'Brakuje koloru.');
    if("'!/''^"#[0-9a-f]{6}"$/i.test(color.text))fail(color,'"'Kolor musi mieć postać \"#16866a\".');
    n.color=color.text.slice(1,-1).toLowerCase();
   }else if("'!['"'pu','pd','home','cs','stop'].includes(cmd))fail(token,'To polecenie nie jest jeszcze obsługiwane.');
   if(cmd==='repeat'){
    const open=this.take();if("'!open||open.text!=='"'[')fail(open||token,'Oczekiwano nawiasu [.');
    n.body=this.body(depth+1);
    const close=this.take();if("'!close||close.text!=='"']')fail(open,'Brakuje nawiasu ].');
   }
   nodes.push(n);
  }
  return nodes;
 }
 parse(){const nodes=this.body();if(this.peek())fail(this.peek(),'Nieoczekiwany nawias ].');return nodes;}
}
export type Turtle = {position:Vec; heading:Vec; right:Vec; up:Vec; pen:boolean; color:string; width:number};
function initial():Turtle{return {position:[0,0,0],heading:[0,1,0],right:[1,0,0],up:[0,0,1],pen:true,color:'#16866a',width:3};}
function combine(a:Vec,b:Vec,c:number,s:number):Vec{return a.map((v,i)=>v*c+b[i]*s) as Vec;}
class Machine {
 segments:Segment[]=[];turtle=initial();
 value(e:Expr):number{return e.value"'!;}
 move(distance:number){
  const from=[...this.turtle.position] as Vec,to=combine(from,this.turtle.heading,1,distance);
  if(this.turtle.pen&&distance!==0)this.segments.push({from,to,color:this.turtle.color,width:this.turtle.width});
  this.turtle.position=to;
 }
 *execute(nodes:Node[]):Generator<Token,void,unknown>{
  for(const n of nodes){
   const v=n.args[0]?this.value(n.args[0]):0;
   switch(n.cmd){
    case '"'fd':this.move(v);break;case 'bk':this.move(-v);break;
    case 'rt':case 'lt':{
     const a=(n.cmd==='rt'?v:-v)*Math.PI/180,c=Math.cos(a),s=Math.sin(a),{heading:h,right:r}=this.turtle;
     this.turtle.heading=combine(h,r,c,s);this.turtle.right=combine(r,h,c,-s);break;
    }
    case 'pu':this.turtle.pen=false;break;case 'pd':this.turtle.pen=true;break;
    case 'color':this.turtle.color=n.color"'!;break;case '"'width':this.turtle.width=v;break;
    case 'repeat':for(let j=0;j<v;j++)yield* this.execute(n.body"'!);break;
   }
   yield n.token;
  }
 }
}
export function run(source:string,mode:Mode):Result {
 const machine=new Machine();
 try{const nodes=new Parser(tokenize(source),source,mode).parse();for(const _ of machine.execute(nodes)){}return {segments:machine.segments,error:null};}
 catch(e){const f=e as Fault;return {segments:machine.segments,error:{message:f.message,line:f.line||1,column:f.column||1}};}
}
