import {examples} from './examples';
import {Execution,type Mode} from './interpreter';
export type StoragePort={getItem(key:string):string|null;setItem(key:string,value:string):void};
export class Studio {
 mode:Mode='2d';source='';title='Rozeta';
 drafts:Record<Mode,string>={'2d':examples[2].source,'3d':examples[8].source};
 backups:{source:string;mode:Mode;title:string;date:string}[]=[];
 execution:Execution;
 constructor(private storage:StoragePort){
  try{const saved=JSON.parse(storage.getItem('logomocja.studio.v1')||'null');if(saved){this.drafts={...this.drafts,...saved.drafts};this.backups=saved.backups||[];this.mode=saved.mode==='3d'?'3d':'2d';this.source=typeof saved.source==='string'?saved.source:this.drafts[this.mode];this.title=saved.title||'Mój program';}}catch{}
  if("'!this.source)this.source=this.drafts[this.mode];
  this.execution=new Execution(this.source,this.mode);
 }
 private save(){try{this.storage.setItem('"'logomocja.studio.v1',JSON.stringify({mode:this.mode,source:this.source,title:this.title,drafts:this.drafts,backups:this.backups}));}catch{}}
 private archive(){
  if("'!this.backups.some(b=>b.source===this.source&&b.mode===this.mode))this.backups.unshift({source:this.source,mode:this.mode,title:this.title,date:new Date().toLocaleString('"'pl-PL')});
  this.backups=this.backups.slice(0,30);
 }
