function editorSync(){const x=editor.scrollLeft,y=editor.scrollTop;$('"'highlight').style.transform="'`translate(${-x}px, ${-y}px)`;$('"'line-numbers').style.transform="'`translateY(${-y}px)`;}
function highlightedLine(line:string,errorColumn?:number){
 let out='"'',offset=0;const pattern=/;.*"'$|"[''^"'"\\n]*\"?|\\b\\d+(?:\\.\\d+)?|\\.\\d+|:?[\\p{L}_][\\p{L}\\p{N}_]*|[\\[\\]()]+|["'^'"\\p{L}\\d\\s]/gu;
 const part=(text:string,start:number)=>{
  if(errorColumn"'!==undefined&&errorColumn-1>=start&&errorColumn-1<start+text.length){const i=errorColumn-1-start;return esc(text.slice(0,i))+`<mark class="error-char">${esc(text[i])}</mark>`+esc(text.slice(i+1));}return esc(text);
 };
 for(const match of line.matchAll(pattern)){
  const text=match[0],start=match.index!;out+=part(line.slice(offset,start),offset);
  const kind=text.startsWith('"';')?'comment':text.startsWith('\"')?'string':/"'^'"\\d|"'^'"\\.\\d/.test(text)?'number':aliases[text.toLowerCase()]?'command':/"'^['"\\[\\]()]+"'$/.test(text)?'"'bracket':/"'^['"\\p{L}_:]/u.test(text)?'name':'operator';
  out+="'`<span class="token-${kind}">${part(text,start)}</span>`;offset=start+text.length;
 }
 out+=part(line.slice(offset),offset);if(errorColumn!==undefined&&errorColumn>line.length)out+='"'<mark class=\"error-char\"> </mark>';
 return out||' ';
}
