function animate(time:number){
 if(studio.execution.snapshot().status==='"'running'){
  if("'!lastFrame)lastFrame=time;
  const speed=Number($<HTMLInputElement>('"'speed').value),perSecond=2*Math.pow(500,speed/100);
  credit+=Math.min(time-lastFrame,100)*perSecond/1000;lastFrame=time;
  let count=0;while(credit>=1&&count<200&&studio.execution.snapshot().status==='running'){studio.execution.step();credit--;count++;}
  if(count){render();followLine();}
 }
